// ── Normalize an incoming WordPress form submission into the Whizz Contacts schema ──
// Point your WordPress form's webhook (CF7 + "Webhook for Contact Form 7", WPForms Pro's
// built-in Webhooks connection, or the Gravity Forms Webhooks Add-On) at this endpoint.
// Whatever plugin you use, try to send clean keys: name, email, phone, message, form.
// The fallbacks below also catch Contact Form 7's raw field names out of the box.

// Edit these two defaults to match your site:
const DEFAULT_BRAND = 'Website Leads';
const DEFAULT_COUNTRY = '';

const b = $input.first().json.body || $input.first().json || {};

const name = b.name || b['your-name'] || b.full_name || b.contactName || '';
const email = b.email || b['your-email'] || '';
const phoneRaw = b.phone || b['your-phone'] || b['tel-843'] || b.mobile || '';
const message = b.message || b['your-message'] || '';
const formName = b.form || b.form_name || b.formName || 'WordPress Form';

// Same normalization as the Whizz frontend: digits only, strip leading trunk 0,
// compare the trailing 9 digits so +971501234567 / 971501234567 / 0501234567 match.
function normalizePhone(phone) {
  if (!phone) return '';
  let digits = String(phone).replace(/\D/g, '');
  digits = digits.replace(/^0+/, '');
  if (digits.length < 7) return digits;
  return digits.slice(-9);
}

return [{
  json: {
    contactName: name || email || 'Website Lead',
    company: name || '',
    phone: phoneRaw,
    phoneKey: normalizePhone(phoneRaw),
    email: email,
    category: message ? message.slice(0, 120) : '',
    source: formName,
    platform: 'Website',
    country: DEFAULT_COUNTRY,
    brand: DEFAULT_BRAND
  }
}];

// ── Duplicate check against every existing contact's phone number ──
function normalizePhone(phone) {
  if (!phone) return '';
  let digits = String(phone).replace(/\D/g, '');
  digits = digits.replace(/^0+/, '');
  if (digits.length < 7) return digits;
  return digits.slice(-9);
}

const lead = $('Normalize Lead').first().json;
const existingRows = $input.all();

let isDuplicate = false;
let duplicateName = '';

if (lead.phoneKey) {
  for (const row of existingRows) {
    const existingPhone = row.json.phone || row.json.whatsapp || row.json['WhatsApp'] || row.json.mobile || '';
    if (normalizePhone(existingPhone) === lead.phoneKey) {
      isDuplicate = true;
      duplicateName = row.json.contactName || row.json.company || row.json.name || 'an existing contact';
      break;
    }
  }
}

return [{ json: { ...lead, isDuplicate, duplicateName } }];
